UPDATE tbl_fixed_expense_candidate
SET next_expected_date = #{nextExpectedDate}
WHERE id = #{candidateId}
  AND user_id = #{userId}
  AND status = 'ACTIVE'
  AND is_excluded = 0
  AND confirmed_at IS NOT NULL
  AND next_expected_date = #{expectedDate}

UPDATE tbl_fixed_expense_candidate
SET status = 'BUFFER',
    next_expected_date = #{nextExpectedDate}
WHERE id = #{candidateId}
  AND user_id = #{userId}
  AND status = 'ACTIVE'
  AND is_excluded = 0
  AND confirmed_at IS NOT NULL
  AND next_expected_date = #{expectedDate}

UPDATE tbl_fixed_expense_candidate
SET status = 'ACTIVE',
    confirmed_at = NULL,
    relapse_detected_at = #{relapseDetectedAt},
    next_expected_date = #{nextExpectedDate}
WHERE id = #{candidateId}
  AND user_id = #{userId}
  AND status = 'BUFFER'
  AND is_excluded = 0
  AND next_expected_date = #{expectedDate}

UPDATE tbl_fixed_expense_candidate
SET status = 'VERIFIED_CANCELLED',
    verified_at = #{verifiedAt}
WHERE id = #{candidateId}
  AND user_id = #{userId}
  AND status = 'BUFFER'
  AND is_excluded = 0
  AND next_expected_date = #{expectedDate}

UPDATE tbl_transaction
SET candidate_id = #{candidateId}
WHERE id = #{transactionId}
  AND user_id = #{userId}
